export const calculateMatchPriority =
  (q: string) =>
  (s: BuildingSuggestion): [number, string] => {
    const url = s.displayUrl || s.url;
    if (url && matchUrl(url)(q)) return [1, url];
    const term = (s.term || '').toLowerCase();
    if (term) {
      if (q.length >= 2 && term.startsWith(q)) return [2, q];
      if (q.length >= 4 && fullTextMatch(q)(term)) return [3, q];
    }

    return [-1, ''];
  };

const mapMatchPriority =
  (q) =>
  (s: BuildingSuggestion): BuildingSuggestion => {
    const priority = calculateMatchPriority(q)(s)[0];
    return { ...s, priority };
  };

const filterPriority = (s: BuildingSuggestion) => s.priority >= 0;

// const filterMatch = (q) => ({ term, url }: { term?: string, url?: string }) => {
//   if (q.length >= 4 && term && fullTextMatch(q)(term)) return true;
//   return matchUrl(url)(q);
// }

export const preparePriorityOrder = (q: string) =>
  flow(map(mapMatchPriority(q)), filter(filterPriority));

