export const formatHistory = (
  q: string,
  engine: Engines,
  isOnlySERP: boolean
): ((list: HistoryPage[]) => BuildingSuggestion[]) =>
  flow(
    (list = []) => {
      if (!q) return list;

      return filter(
        (page: HistoryPage) =>
          calculateMatchPriority(q)({ url: page.url, term: page.title })[0] >= 0
      )(list);
    },
    map((page: HistoryPage) => {
      const usedEngine = Object.values(ENGINES).find(({ url }) =>
        page.url.match(new URL(url).host)
      );
      if (usedEngine) {
        const term = new URLSearchParams(page.url.split('?')[1]).get(
          usedEngine.q
        );
        if (term) {
          return createOrganicSuggestion(
            { id: page.url, term, type: 'historyOrganic' },
            engine
          );
        } else {
          return null;
        }
      }

      if (isOnlySERP) return null;

      return {
        id: page.url,
        type: 'history',

        term: page.title || createTermFromUrl(page.url),
        url: page.url,
        favIconUrl: (page.favIconUrl || '').match('https://')
          ? page.favIconUrl
          : getFaviconUrl(page.url),
      };
    }),
    filter(Boolean),
    (list) => {
      if (!q) {
        return flow(
          uniqBy((s: BuildingSuggestion) => {
            try {
              if (s.type === 'history' && s.url) {
                return new URL(s.url).host;
              }
            } catch (err) {
              console.error('uniqBy', err);
            }

            return s.url;
          }),
          (l) => l.slice(0, 10)
        )(list);
      }

      return filter((s: BuildingSuggestion) =>
        s.type === 'organic'
          ? calculateMatchPriority(q)({ term: s.term })[0] >= 0
          : true
      )(list);
    }
  );

