export const formatZeropark =
  (q: string) =>
  (zp: Zeropark): Suggestion[] => {
    if (!q || q.length < 3 || !zp?.brands?.length) return [];

    try {
      const term = q.toLowerCase();
      return flow(
        map((brand: ZeroparkBrand) => {
          const found = [
            brand.brand.url,
            brand.brand.name,
            ...brand.keywords,
          ].find((v) => {
            const vv = v.toLowerCase();
            if (vv.toLowerCase().startsWith(term)) return true;
            if (term.length > 4) return vv.includes(term) || term.includes(vv);
            return false;
          });

          return found
            ? {
                type: 'ad',
                id: brand.brand.url,
                term: found === brand.brand.url ? brand.brand.name : found,
                displayUrl: brand.brand.url,
                url: zp.clickUrl
                  .replace(/\${brand.url}/g, brand.brand.url)
                  .replace(/\${brand.name}/g, brand.brand.name),
                favIconUrl: createFaviconUrl(brand.brand.url),
                priority: found.startsWith(term) ? 1 : 2,
                provider: 'zeropark',
                revenue: brand.eCpc,
              }
            : null;
        }),
        filter(Boolean),
        sortBy('priority'),
        (list: Suggestion[]) => list.slice(0, 2)
      )(zp.brands);
    } catch (err) {
      // TODO: track it
      console.error('formatZeropark', err);
      return [];
    }
  };

