const createUrlSuggestion = (s: BuildingSuggestion): BuildingSuggestion => {
  const url = withHttp(s.url || s.term);
  return {
    ...s,
    url,
    type: s.type || 'url',
    term: s.term || createTermFromUrl(url),
    favIconUrl: getFaviconUrl(url),
  };
};

export const createOrganicUrl = (
  s: BuildingSuggestion,
  engine: Engines
): string => {
  const TARGET_BROWSER = process.env.TARGET_BROWSER || 'chrome';
  const { url, q } = ENGINES[engine] || {};

  const searchParams = new URLSearchParams({
    ...s.query,
    [q]: s.term,
    ...(['oh', 'bing'].includes(engine) && {
      extensionVersion: process.env.APP_VERSION,
      utm_source:
        TARGET_BROWSER.charAt(0).toUpperCase() + TARGET_BROWSER.slice(1),
      utm_medium: 'Extension:ntp',
    }),
  });

  return `${url}?${searchParams}`;
};

export const createOrganicSuggestion = (
  s: BuildingSuggestion,
  engine: Engines
): BuildingSuggestion => ({
  ...s,
  type: s.type || 'organic',
  url: createOrganicUrl(s, engine),
});

export const decodeTerm = (s: BuildingSuggestion): BuildingSuggestion => {
  const term = s.term || '';
  if (term.startsWith('http:') || term.startsWith('https:')) {
    try {
      return { ...s, term: new URL(term).toString() };
    } catch (err) {
      return s;
    }
  }

  return s;
};

export const createFormatOrganic = (
  q: string,
  engine: Engines
): ((list: string[] | BuildingSuggestion[]) => Suggestion[]) =>
  flow(
    map((s) => (typeof s === 'string' ? { term: s } : s)),
    map(decodeTerm),
    map(
      (s: BuildingSuggestion): BuildingSuggestion =>
        checkIsUrl(s.term)
          ? createUrlSuggestion({ ...s, url: s.term })
          : createOrganicSuggestion(s, engine)
    ),
    (list) => [
      createOrganicSuggestion({ term: q, type: 'organicProvided' }, engine),
      ...list,
    ],
    (list: BuildingSuggestion[]): Suggestion[] => {
      if (!list.length) {
        return [createOrganicSuggestion({ term: q }, engine) as Suggestion];
      }

      if (!checkIsUrl(q)) return list as Suggestion[];
      if (list[0]?.type === 'url') return list as Suggestion[];
      return [
        createUrlSuggestion({ term: q, type: 'urlCandidate' }),
        createOrganicSuggestion({ term: q }, engine),
        ...list,
      ] as Suggestion[];
    }
  );

export const createSearchTagSuggestion =
  (searchTag: SearchTag) =>
  (s: Suggestion): Suggestion => {
    const sTerm = s.term.toLowerCase();
    const tagTerm = searchTag.s.toLowerCase();
    const term = (
      sTerm.startsWith(tagTerm) ? s.term.substr(tagTerm.length) : s.term
    ).trim();
    const url = searchTag.u.replace('{{{s}}}', encodeURI(term));

    return {
      ...s,
      term,
      url,
      type: 'searchTag',
      favIconUrl: getFaviconUrl(url),
    };
  };

