const formatAdmarketplaceAd = (s: AdMarketplacePaid): BuildingSuggestion => ({
  type: 'ad',
  provider: 'adMarketplace',
  revenue: 0.5,
  term: s.term,
  url: s.click_url,
  favIconUrl: s.image_url,
  impressionUrl: s.impression_url,
  displayUrl: s.brand ? s.brandDomain : null,
});

export const createFormatAdMarketplace =
  (q: string, engine: Engines) =>
  (data: AdMarketplaceData): Suggestion[] => {
    const organic: AdMarketplaceOrganic[] = Array.isArray(
      data?.organic_suggestions
    )
      ? data.organic_suggestions
      : [];
    const paid: AdMarketplacePaid[] = Array.isArray(data?.paid_suggestions)
      ? data.paid_suggestions
      : [];

    return flow(
      map((s: AdMarketplaceOrganic) =>
        s.paid_suggestion_ids
          ? s.paid_suggestion_ids.map((id) => paid.find((p) => p.id === id))
          : s
      ),
      flatten,
      filter(Boolean),
      groupBy(({ impression_url }) => (impression_url ? 'ad' : 'organic')),
      (groups: {
        ad: AdMarketplacePaid[];
        organic: AdMarketplaceOrganic[];
      }) => {
        const ads = groups.ad || [];
        const organic = (groups.organic || []).map((s) => s.term);

        return [
          ...ads.map(formatAdmarketplaceAd),
          ...createFormatOrganic(q, engine)(organic),
        ];
      }
    )(organic);
  };

export const createFormatAdMarketplaceLongtail =
  (q: string, engine: Engines) =>
  ([data, organic]: [
    AdMarketplaceLongTailData,
    string[] | BuildingSuggestion[]
  ]): Suggestion[] => {
    const organicList = createFormatOrganic(q, engine)(organic);

    if (!data.count) return organicList;

    const ads = data.adlistings.listing.map(
      (listining): Suggestion => ({
        id: listining.adId,
        url: listining.clickurl,
        displayUrl: listining.displayurl,
        impressionUrl: listining.impressionurl,
        term: listining.title,
        // label: listining.description,
        type: 'ad',

        favIconUrl: getFaviconUrl(withHttp(listining.displayurl)),
        provider: 'adMarketplace_search',
        revenue: 0.5,
      })
    );

    return [...ads, ...organicList];
  };

