export const formatPopularWebsites = (
  q: string
): ((list: PopularWebsite[]) => Suggestion[]) =>
  flow(
    preparePriorityOrder(q),
    map((s: PopularWebsite) => ({ ...s, type: 'website' })),
    map(createUrlSuggestion)
  );

