const ORDER = [
  'url',
  'website',
  'ad',
  'history',
  'historyOrganic',
  'tile',
  'website',
  'url',
  'urlCandidate',
  'organicProvided',
  'organic',
  'searchTag',
  'openTab',
];

const sortSuggestions =
  (q: string) =>
  (s: BuildingSuggestion): number => {
    if (s.type === 'ad') return 0;

    const priority = calculateMatchPriority(q)(s);
    const isOrganic = [
      'organic',
      'ad',
      'organicProvided',
      'searchTag',
    ].includes(s.type);
    // const isOrganic = ['organic', 'organicProvided', 'searchTag'].includes(s.type);

    const result = [
      (() => {
        if (isOrganic) return 2;
        return priority[0] === -1 ? 3 : priority[0];
      })(),
      ORDER.indexOf(s.type),
      // shorter higher priority within it's group, ignore organic & organicProvider
      !priority[1] || isOrganic ? '00' : `0${priority[1].length}`.substr(-2),
    ].join('');

    return Number(result);
  };

const prettifyUrl = flow(
  urlPrettifiers.removePrefix,
  urlPrettifiers.removeSuffix
);

let $input;
export const getTotalLimit = (): number => {
  if (typeof window === 'undefined') return 10;

  if (typeof document !== 'undefined') {
    $input = $input || document.querySelector('[name="q"]');
  }

  const { y } =
    typeof document === 'undefined'
      ? { y: 330 }
      : $input?.getBoundingClientRect() || { y: 330 };

  const dimensions = { suggestion: 40, inputFromTop: y };
  return Math.floor(
    (window.innerHeight - dimensions.inputFromTop - 50) / dimensions.suggestion
  );
};

const limitSuggestions = (q: string) => (list) => {
  const limit = getTotalLimit();

  if (!q && (list.length <= limit || !limit)) return list;

  const groups = groupBy('type')(list);

  const max2Categories = [
    'history',
    'historyOrganic',
    'tile',
    'website',
    'openTab',
  ];

  const specialCategories = flow(
    map((type: string) => (groups[type] || []).slice(0, 2)),
    zipAll,
    flatten,
    filter(Boolean),
    (list) => list.slice(0, 4)
  )(max2Categories);

  return list
    .filter((s: BuildingSuggestion) =>
      max2Categories.includes(s.type) ? specialCategories.includes(s) : true
    )
    .slice(0, limit);
};

const filterBlacklist = (featureFlags) => {
  const adBlacklist = featureFlags.AD_AUTOSUGGESTION_BLACKLIST || [];

  if (!adBlacklist.length) {
    return (list) => list;
  }

  return filter(
    (s: BuildingSuggestion) =>
      !adBlacklist.find(([key, value]) => s[key] === value)
  );
};

export const mapId = (s: BuildingSuggestion): Suggestion =>
  s.id ? (s as Suggestion) : ({ ...s, id: s.id || s.url } as Suggestion);

const getHost = (url) => {
  try {
    return new URL(url).host;
  } catch (err) {
    return url;
  }
};

export const formatFinalData = (
  q: string,
  featureFlags: FeatureFlags,
  list: Suggestion[]
): Suggestion[] =>
  flow(
    filterBlacklist(featureFlags),
    map(mapId),
    sortBy(sortSuggestions(q)),
    uniqBy((s: BuildingSuggestion) => prettifyUrl(s.displayUrl || s.url)),
    uniqBy(
      (s: BuildingSuggestion) =>
        `${(s.term || '').toLowerCase().trim()}:${getHost(s.url)}`
    ),
    limitSuggestions(q)
  )(list);

const calendarFav =
  'https://calendar.google.com/googlecalendar/images/favicons_2020q4/calendar_3.ico';
const faviconMap = {
  'https://calendar.google.com': calendarFav,
  '/calendar/b/0/render': calendarFav,
  'https://www.google.com/calendar': calendarFav,

  'https://drive.google.com':
    'https://ssl.gstatic.com/images/branding/product/1x/drive_2020q4_32dp.png',
  'https://mail.google.com':
    'https://ssl.gstatic.com/ui/v1/icons/mail/rfr/gmail.ico',
};

export const createFaviconUrl = (domain: string, sz = '32'): string =>
  `https://www.google.com/s2/favicons?${new URLSearchParams({
    domain,
    sz,
  })}`;

export const getFaviconUrl = (url: string, sz = '32'): string => {
  try {
    const { origin, pathname } = new URL(url);
    return (
      faviconMap[origin] ||
      faviconMap[pathname] ||
      faviconMap[`${origin}${pathname}`] ||
      createFaviconUrl(new URL(url).origin, sz)
    );
  } catch (err) {
    return null;
  }
};
